package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import static org.junit.jupiter.api.Assertions.*;

class JdbcInviteDiagnosisPoliciesTest extends JdbcInvitationRewardsTest {
 InviteDiagnosisPolicies diagnosis;
 @BeforeEach void diagnosis(){jdbc.update("DELETE FROM invite_diagnosis_policy");diagnosis=new InviteDiagnosisPolicies(db,new OperatorIdentity(jdbc,null,new DataSourceTransactionManager(jdbc.getDataSource())));}
 ObjectNode unlock(int n){return json.createObjectNode().put("required_count",n).put("source_note","用户确认的当月规则").put("valid_from",clock.value.minusSeconds(10).toString()).put("valid_to",clock.value.plusSeconds(90*86400).toString());}
 long rule(int n){return diagnosis.create(operator,key(),unlock(n)).path("data").path("id").longValue();}
 void enable(long id){diagnosis.status(operator,id,key(),statusBody(1,"PUBLISHED"));}
 @Test void missingPolicyIsUnknownAndPolicyAloneNeverGrants(){assertEquals("UNKNOWN",diagnosis.current(owner).get("state"));long id=rule(1);enable(id);assertEquals("LOCKED",diagnosis.current(owner).get("state"));assertEquals(false,diagnosis.current(owner).get("service_available"));assertEquals(0,count("coupon_issue"));assertEquals(0,count("invite_reward_batch"));}
 @Test void onlyVerifiedQualifiedOwnerInvitesCountAndDisabledInviteeRevokes(){long id=rule(1);enable(id);String c=promo("user");qualify(c,"TEST",101);qualify(c,"UNKNOWN",102);assertEquals("LOCKED",diagnosis.current(owner).get("state"));long u=qualify(c,"VERIFIED_WECHAT",103);assertEquals("ELIGIBLE",diagnosis.current(owner).get("state"));assertEquals("LOCKED",diagnosis.current(peer).get("state"));jdbc.update("UPDATE user SET status=0 WHERE id=?",u);assertEquals("LOCKED",diagnosis.current(owner).get("state"));jdbc.update("UPDATE user SET status=1 WHERE id=?",u);assertEquals("ELIGIBLE",diagnosis.current(owner).get("state"));}
 @Test void beijingMonthBoundaryRemovesPreviousMonthEligibility(){clock.value=Instant.parse("2026-10-31T15:59:59Z");long id=rule(1);enable(id);qualify(promo("user"),"VERIFIED_WECHAT",104);var eligible=diagnosis.current(owner);assertEquals("ELIGIBLE",eligible.get("state"));assertEquals("2026-10-31T16:00:00Z",eligible.get("usable_until"));clock.value=clock.value.plusSeconds(1);var next=diagnosis.current(owner);assertEquals("2026-11",next.get("month"));assertEquals(0L,next.get("qualified_count"));assertEquals("LOCKED",next.get("state"));assertNull(next.get("usable_until"));}
 @Test void policyStopFutureAndExpiryAreImmediatelyRechecked(){long id=rule(1);enable(id);qualify(promo("user"),"VERIFIED_WECHAT",105);assertEquals("ELIGIBLE",diagnosis.current(owner).get("state"));diagnosis.status(operator,id,key(),statusBody(2,"STOPPED"));assertEquals("UNKNOWN",diagnosis.current(owner).get("state"));var b=unlock(1).put("valid_from",clock.value.plusSeconds(60).toString()).put("valid_to",clock.value.plusSeconds(120).toString());long future=diagnosis.create(operator,key(),b).path("data").path("id").longValue();enable(future);assertEquals("NOT_STARTED",diagnosis.current(owner).get("state"));clock.value=clock.value.plusSeconds(60);assertEquals("ELIGIBLE",diagnosis.current(owner).get("state"));assertEquals(clock.value.plusSeconds(60).toString(),diagnosis.current(owner).get("usable_until"));clock.value=clock.value.plusSeconds(60);assertEquals("EXPIRED",diagnosis.current(owner).get("state"));}
 @Test void independentInvitePermissionCasAndReplayAuthorization(){long id=rule(2);var b=unlock(3).put("expected_revision",1);diagnosis.update(operator,id,key(),b);assertEquals(409,code(()->diagnosis.update(operator,id,key(),b)));diagnosis.status(operator,id,key(),statusBody(2,"PUBLISHED"));assertEquals(409,code(()->diagnosis.update(operator,id,key(),unlock(4).put("expected_revision",3))));String k=key();var receipt=diagnosis.create(operator,k,unlock(5));assertEquals(receipt,diagnosis.create(operator,k,unlock(5)));jdbc.update("UPDATE operator_account SET can_invite=0,can_coupon=1 WHERE id=1");assertEquals(403,code(()->diagnosis.list(operator,1)));assertEquals(403,code(()->diagnosis.create(operator,k,unlock(5))));}
 @Test void twoOperatorsCannotPublishTwoActiveRules()throws Exception{long a=rule(1),b=rule(2);jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,can_invite) VALUES(2,'diagnosis-peer','unused','13800000001',1)");var op2=new OperatorActor(2,session(2,"operator_account","OPERATOR",OperatorActor.APP,null),Instant.now().plusSeconds(600));var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{var fs=new ArrayList<Future<Integer>>();for(var pair:List.of(new Object[]{operator,a},new Object[]{op2,b}))fs.add(pool.submit(()->{start.await();try{diagnosis.status((OperatorActor)pair[0],(Long)pair[1],key(),statusBody(1,"PUBLISHED"));return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}}));start.countDown();var result=new ArrayList<Integer>();for(var f:fs)result.add(f.get(30,TimeUnit.SECONDS));Collections.sort(result);assertEquals(List.of(200,409),result);}finally{pool.shutdownNow();}}
 @Test void auditFailureRollsBackAndStrictBodiesRejectClientEligibility(){jdbc.execute("CREATE TRIGGER fail_coupon_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic rollback'");assertEquals(503,code(()->diagnosis.create(operator,key(),unlock(1))));assertEquals(0,count("invite_diagnosis_policy"));for(String raw:List.of(unlock(1).put("eligible",true).toString(),unlock(0).toString(),unlock(1).put("required_count",1.5).toString(),unlock(1)+"{}",unlock(1).toString().replace("\"required_count\":1","\"required_count\":1,\"required_count\":2")))assertThrows(Exception.class,()->InviteDiagnosisPolicies.input(raw,false));}
}
